// 02 - Basics: a few µTest++ checks to copy from.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>

#include <cerrno>
#include <cstdint>

// Registers itself with the runner of this image; there is no central list
// of suites to keep in step with the files. run_suites () runs the static
// suites sorted by name, so the "NN -" prefix is the report order.
mt::static_suite suite_basics{
  "02 - Basics", mtp_board::runner (), [] (mt::suite& ts) {
    ts.test ("comparisons", [] (auto& t) {
      t.expect (mt::eq (6 * 7, 42)) << "eq";
      t.expect (mt::all_of (mt::lt (1, 2), mt::ge (2, 2))) << "lt and ge, combined";
      t.expect (mt::approx (0.1 + 0.2, 0.3, 1e-9)) << "floating point, with a tolerance";
    });

    ts.test ("a kernel object", [] (auto& t) {
      os::rtos::semaphore_binary sem{ "mtp-example", 0 };
      t.expect (mt::eq (sem.try_wait (), mtp::code (EWOULDBLOCK))) << "empty";
      t.expect (mt::eq (sem.post (), mtp::ok)) << "post";
      t.expect (mt::eq (sem.try_wait (), mtp::ok)) << "take";
    });

    ts.test_each ("one case per value", { 1u, 2u, 3u },
                  [] (auto& t, unsigned n) { t.expect (mt::gt (n, 0u)) << "positive"; });
  }
};
